    deleted = 0
    AND status = #{status}
    AND (route_path LIKE CONCAT('%', #{keyword}, '%') OR route_name LIKE CONCAT('%', #{keyword}, '%') OR menu_name LIKE CONCAT('%', #{keyword}, '%'))

